INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) VALUES ('chunk_08ea21a82a4d8abb0dd3c0e2','wiki/sources/fragenkatalog-annex-vii-data.md',64,'Seite 33','1.47 Aus nachvollziehbaren Gründen kann es ja vorkommen, dass DB InfragGO an den

Fahrzeiten und/oder Laufweg zwischen FPE/NAÄ und BauFplo Änderungen vornehmen

muss oder es aktualisierte Versionen zu einer bestehenden BauFplo gibt. In diesen beiden Fällen müsste das EVU doch auch zusätzlich eine NAÄ bekommen (FPE wahrscheinlich wegen Fristablauf nicht). Nur das EVU kann ja beurteilen, ob mit den vorhandenen

Produktionsressourcen die geänderte Fahrlage auch produziert werden kann. Bekommen wir in solchen Fällen (entweder Unterschiede zwischen FPE/NAÄ und BauFplo oder

mit aktualisierten Versionen einer BauFplo) auch parallel immer eine NAÄ?

Zu einer BauFplo gibt es immer das entsprechende NAÄ dazu.

1.48 Was ist, wenn wir umlaufbedingt die Zugcharakteristik später ändern müssen?

Wird während der Konsultations-Stellungnahmephase zu einem GPE umlaufbedingt eine Anpassung der Zugcharakteristik erforderlich und hierzu Stellungnahme vom ZB abgegeben, wird

lediglich das GPE bzw. in das GPEnS sowie ggf. das FPE die geänderte Zugcharakteristik aufgenommen, sofern diese umsetzbar ist angepasst. Wird eine berechtigte Änderung nach dem

Versand des FPE ausgelöst dieser Konsultationsphase notwendig, wird eine neue FPE, NAÄ

und digitale BauFplo mit der geänderten Zugcharakteristik ausgestellt, sofern umsetzbar. Alternativ kann eine Änderungsbestellung getätigt werden. Es wird auf Abschnitt 10 Abs. 7 der

Richtlinie 402.0305 verwiesen.

V.IWF 41 Fragenkatalog 33',200,'{"canonical_url":null,"normalized_sha256":"964d24cd41f50e75b8bb1d06f76d9cc47af41a110c36b4bb8a20597a3a823500","page":33,"source_id":"src_49e6bd4a29f18c068815","source_sha256":"ad7a22df2cd5529c685aa7d10d878783f41dcf2902c4bb7c1a233c97810359ca","source_version_id":"sv_ad7a22df2cd5529c685aa7d1"}','6ac942fa11d12b98dba50ea1580339e3b6d29a426816ce39117f787e8dd09c68');

